-- =============================================================================
-- SkillVerse AI: Complete Database Seed (prisma/seed.sql)
-- Seeds 110 trend signals, 104 ESCO roles (with 1024-dim vectors), and 17 SDG targets
-- Compatible with 'prisma db execute --file prisma/seed.sql' and Supabase SQL Editor
-- =============================================================================

-- 1. SEED TREND SIGNALS (110 records)
ON CONFLICT ("skillName") DO UPDATE SET
  category = EXCLUDED.category,
  "currentWindowC" = EXCLUDED."currentWindowC",
  "pastWindowC" = EXCLUDED."pastWindowC",
  "velocityVs" = EXCLUDED."velocityVs",
  status = EXCLUDED.status,
  sources = EXCLUDED.sources,
  "updatedAt" = EXCLUDED."updatedAt";

-- 2. SEED UN SDG TARGETS (17 records)
ON CONFLICT (target_code) DO UPDATE SET
  goal_number = EXCLUDED.goal_number,
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  embedding = EXCLUDED.embedding;

-- 3. SEED ESCO / FUTURE ROLES (104 records with 1024-dim dense vectors)
ON CONFLICT (role_id) DO UPDATE SET
  title = EXCLUDED.title,
  title_ms = EXCLUDED.title_ms,
  title_zh = EXCLUDED.title_zh,
  industry = EXCLUDED.industry,
  required_skills = EXCLUDED.required_skills,
  sdg_alignments = EXCLUDED.sdg_alignments,
  scenario_multipliers = EXCLUDED.scenario_multipliers,
  radar_requirements = EXCLUDED.radar_requirements,
  embedding = EXCLUDED.embedding,
  updated_at = EXCLUDED.updated_at;
